<script setup lang="ts">
// 系统 AI 配置页：/manage/ai-system-config（管理 tab 侧边栏，门禁 i-manage-ai）。
//
// 定位：站方系统级大模型配置（接入凭据 + 各能力模型名），替代后端原来的 yaml `ai` 配置段，
// 改为落数据库维护。后端每次调用读取，保存后下一次调用即生效（不需要重启或重新部署）。
// 用户个人的 BYOK 密钥仍在「AI 厂商」页维护，两者互不影响。

import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, formatDate } from "@/util/tips";
import { GetAiSystemConfig, PostAiSystemConfigSet } from "@/apis/ai-system-config";
import type { AiSystemConfigView } from "@/types/ai-system-config";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
// 移动端把标签放控件上方：170px 的固定标签宽在窄屏会把输入框挤到几乎不可用
const { isMobile } = useBreakpoint();

// 表单模型：api_key 只用于提交（后端只回掩码，留空表示不修改已保存的密钥）
interface SystemConfigForm {
  base_url: string;
  api_key: string;
  enrich_model: string;
  test_plan_model: string;
  test_code_model: string;
  test_data_model: string;
  test_generator_model: string;
  polish_model: string;
}

const emptyForm = (): SystemConfigForm => ({
  base_url: "",
  api_key: "",
  enrich_model: "",
  test_plan_model: "",
  test_code_model: "",
  test_data_model: "",
  test_generator_model: "",
  polish_model: "",
});

const form = ref<SystemConfigForm>(emptyForm());

// 只读元信息与表单分开，避免被保存请求带回后端
const apiKeyMask = ref("");
const hasApiKey = ref(false);
const updateUser = ref("");
const modifyTime = ref("");

const loading = ref(false);
const saving = ref(false);

// 最近修改时间：RFC3339 → 本地可读；空值显示「—」
const modifyTimeText = computed(() => (modifyTime.value ? formatDate(modifyTime.value) : "—"));

// 最近修改人 + 时间，两者都为空时整体显示「—」
const lastModifyText = computed(() => {
  if (!updateUser.value && !modifyTime.value) {
    return "—";
  }
  return `${updateUser.value || "—"} ${modifyTimeText.value}`;
});

// 密钥掩码提示：只在已保存密钥时展示
const apiKeyHelp = computed(() => (hasApiKey.value ? `当前密钥：${apiKeyMask.value}` : ""));

// 用后端返回的视图回填表单。api_key 始终清空：不回显明文，留空即「不修改」
const applyView = (view: AiSystemConfigView) => {
  form.value = {
    base_url: view.base_url ?? "",
    api_key: "",
    enrich_model: view.enrich_model ?? "",
    test_plan_model: view.test_plan_model ?? "",
    test_code_model: view.test_code_model ?? "",
    test_data_model: view.test_data_model ?? "",
    test_generator_model: view.test_generator_model ?? "",
    polish_model: view.polish_model ?? "",
  };
  apiKeyMask.value = view.api_key_mask ?? "";
  hasApiKey.value = view.has_api_key ?? false;
  updateUser.value = view.update_user ?? "";
  modifyTime.value = view.modify_time ?? "";
};

const load = async () => {
  loading.value = true;
  try {
    const res = await GetAiSystemConfig();
    if (res.code === 0 && res.data) {
      applyView(res.data);
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "加载系统 AI 配置失败");
  } finally {
    loading.value = false;
  }
};

const onSave = async () => {
  // 最简校验：空地址等于关闭系统 AI，先在前端拦下
  const baseUrl = form.value.base_url.trim();
  if (!baseUrl) {
    ShowTextTipsError(globalProperties, "接入地址不能为空（空地址等于关闭系统 AI）");
    return;
  }

  saving.value = true;
  try {
    const apiKey = form.value.api_key.trim();
    const res = await PostAiSystemConfigSet({
      base_url: baseUrl,
      // 留空即不带该字段，后端按「不修改已保存的密钥」处理
      api_key: apiKey ? apiKey : undefined,
      enrich_model: form.value.enrich_model.trim(),
      test_plan_model: form.value.test_plan_model.trim(),
      test_code_model: form.value.test_code_model.trim(),
      test_data_model: form.value.test_data_model.trim(),
      test_generator_model: form.value.test_generator_model.trim(),
      polish_model: form.value.polish_model.trim(),
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 以保存后的最新视图刷新表单（含新的密钥掩码与最近修改信息）
    if (res.data) {
      applyView(res.data);
    }
    ShowTextTipsInfo(globalProperties, "已保存，系统下一次调用即生效");
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "保存失败，请稍后重试");
  } finally {
    saving.value = false;
  }
};

onMounted(() => {
  void load();
});
</script>

<template>
  <div class="manage-ai-system-config">
    <t-card class="ai-system-config-header-card">
      <div class="ai-system-config-header">
        <h2>系统 AI 配置</h2>
      </div>
      <p class="ai-system-config-subtitle">
        这里维护站方系统级的大模型配置（接入凭据 + 各能力使用的模型名），保存在数据库、改完即时生效，无需重启或重新部署。用户个人的 BYOK 密钥仍在「AI 厂商」页维护，与这里互不影响。
      </p>
    </t-card>

    <t-card class="ai-system-config-body-card">
      <t-loading :loading="loading">
        <t-form
          :data="form"
          :label-align="isMobile ? 'top' : 'right'"
          :label-width="isMobile ? undefined : '170px'"
          :disabled="loading || saving"
          class="ai-system-config-form"
        >
          <!-- 1. 接入凭据 -->
          <div class="ai-system-config-group">接入凭据</div>
          <t-form-item label="接入地址" help="OpenAI 兼容的接入地址，如 https://api.deepseek.com">
            <t-input v-model="form.base_url" placeholder="https://api.deepseek.com" />
          </t-form-item>
          <t-form-item label="API 密钥" :help="apiKeyHelp">
            <t-input v-model="form.api_key" type="password" placeholder="留空表示不修改已保存的密钥" />
          </t-form-item>

          <!-- 2. 各能力使用的模型 -->
          <div class="ai-system-config-group">模型</div>
          <t-form-item label="AI 审阅模型" help="题目摘要 / 标签 / 难度 / 质量审阅使用的模型">
            <t-input v-model="form.enrich_model" placeholder="如 deepseek-chat" />
          </t-form-item>
          <t-form-item label="测试数据 · 规划模型" help="测试数据生成：规划阶段使用的模型">
            <t-input v-model="form.test_plan_model" placeholder="如 deepseek-reasoner" />
          </t-form-item>
          <t-form-item label="测试数据 · 参考代码模型" help="测试数据生成：编写参考代码使用的模型">
            <t-input v-model="form.test_code_model" placeholder="如 deepseek-chat" />
          </t-form-item>
          <t-form-item label="测试数据 · 输入生成模型" help="测试数据生成：生成测试输入使用的模型">
            <t-input v-model="form.test_data_model" placeholder="如 deepseek-chat" />
          </t-form-item>
          <t-form-item label="测试数据 · 生成器模型" help="测试数据生成：生成器代码模型，留空则用参考代码模型">
            <t-input v-model="form.test_generator_model" placeholder="留空则用参考代码模型" />
          </t-form-item>
          <t-form-item label="题面美化模型" help="题面美化（排版与表述润色）使用的模型">
            <t-input v-model="form.polish_model" placeholder="如 deepseek-chat" />
          </t-form-item>
        </t-form>

        <div class="ai-system-config-actions">
          <t-space>
            <t-button theme="primary" :loading="saving" @click="onSave">保存</t-button>
            <t-button variant="outline" :disabled="loading || saving" @click="load">重新加载</t-button>
          </t-space>
          <span class="ai-system-config-modify">最近修改：{{ lastModifyText }}</span>
        </div>
      </t-loading>
    </t-card>
  </div>
</template>

